class DoctorDashboard extends ConsumerStatefulWidget { const DoctorDashboard({required this.user, super.key}); final AppUser user; @override ConsumerState<DoctorDashboard> createState()=>_DoctorDashboardState(); }
class _DoctorDashboardState extends ConsumerState<DoctorDashboard> {
 int index=0;
 @override Widget build(BuildContext context){
   final pages=[_Overview(user:widget.user), const _Queue(), const _DoctorMessages(), const _Profile()];
   return Scaffold(backgroundColor: AppTheme.background, body: SafeArea(child: IndexedStack(index:index,children:pages)), bottomNavigationBar:_Nav(index:index,onChanged:(v)=>setState(()=>index=v), labels:const ['الرئيسية','الطابور','الرسائل','حسابي'], icons:const [Icons.space_dashboard_rounded,Icons.people_alt_rounded,Icons.chat_bubble_rounded,Icons.person_rounded]));
 }
}
class _Overview extends ConsumerWidget { const _Overview({required this.user}); final AppUser user;
 @override Widget build(BuildContext c,WidgetRef ref){ final ap=ref.watch(appointmentsProvider); return RefreshIndicator(onRefresh:()async=>ref.invalidate(appointmentsProvider),child:ListView(padding:const EdgeInsets.fromLTRB(20,16,20,110),children:[
  Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('صباح الخير 👋',style:Theme.of(c).textTheme.bodyMedium),const SizedBox(height:4),Text('د. ${user.fullName}',style:Theme.of(c).textTheme.headlineSmall)])),IconButton.filledTonal(onPressed:()=>ref.invalidate(appointmentsProvider),icon:const Icon(Icons.refresh_rounded))]),
  const SizedBox(height:20), _HeroCard(user:user), const SizedBox(height:18),
  Row(children:[Expanded(child:_Metric(title:'مواعيد اليوم',value:ap.when(data:(x)=>'${x.length}',loading:()=> '—',error:(_,_)=>'!'),icon:Icons.calendar_month_rounded)),const SizedBox(width:12),Expanded(child:_Metric(title:'قيد الانتظار',value:ap.when(data:(x)=>'${x.where((a)=>a.status=='waiting').length}',loading:()=> '—',error:(_,_)=>'!'),icon:Icons.hourglass_bottom_rounded))]),
  const SizedBox(height:22),Text('مواعيد اليوم',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:10),
  ap.when(data:(items)=>items.isEmpty?_Empty(text:'لا توجد مواعيد اليوم'):Column(children:items.take(8).map((a)=>_AppointmentTile(a:a,doctor:true)).toList()),loading:()=>const _LoadingCards(),error:(e,_)=>_ErrorCard(message:e.toString(),onRetry:()=>ref.invalidate(appointmentsProvider)))
 ])); }
}
class _HeroCard extends StatelessWidget{const _HeroCard({required this.user});final AppUser user;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:AppTheme.heroGradient,borderRadius:BorderRadius.circular(30),boxShadow:AppTheme.shadowElevated),child:Row(children:[Container(width:58,height:58,decoration:BoxDecoration(color:Colors.white.withOpacity(.18),shape:BoxShape.circle),child:const Icon(Icons.medical_services_rounded,color:Colors.white,size:30)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('عيادتك اليوم',style:TextStyle(color:Colors.white70)),const SizedBox(height:4),Text(user.subscriptionActive==true?'الاشتراك نشط':'حالة الاشتراك تحتاج مراجعة',style:const TextStyle(color:Colors.white,fontSize:18,fontWeight:FontWeight.w800))]))]));}
class _Metric extends StatelessWidget{const _Metric({required this.title,required this.value,required this.icon});final String title,value;final IconData icon;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(17),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(22),boxShadow:AppTheme.shadowCard),child:Row(children:[Container(width:44,height:44,decoration:BoxDecoration(color:AppTheme.primary.withOpacity(.1),borderRadius:BorderRadius.circular(14)),child:Icon(icon,color:AppTheme.primary)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:AppTheme.textSecondary,fontSize:12)),const SizedBox(height:3),Text(value,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800))]))]));}
class _AppointmentTile extends StatelessWidget{const _AppointmentTile({required this.a,required this.doctor});final dynamic a;final bool doctor;@override Widget build(BuildContext c)=>Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20),border:Border.all(color:AppTheme.borderLight)),child:Row(children:[Container(width:46,height:46,alignment:Alignment.center,decoration:BoxDecoration(color:AppTheme.primary.withOpacity(.1),borderRadius:BorderRadius.circular(15)),child:Text('#${a.queueNumber}',style:const TextStyle(color:AppTheme.primary,fontWeight:FontWeight.w800))),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(doctor?(a.patientName??'مريض'):(a.doctorName??'طبيب'),style:const TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:4),Text(doctor?(a.patientPhone??''):(a.doctorSpecialty??''),style:const TextStyle(color:AppTheme.textSecondary,fontSize:12))])),_Status(status:a.status)]));}
class _Status extends StatelessWidget{const _Status({required this.status});final String status;@override Widget build(BuildContext c){final label={'waiting':'انتظار','in_progress':'قيد الفحص','done':'مكتمل','completed':'مكتمل','cancelled':'ملغى'}[status]??status;return Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:7),decoration:BoxDecoration(color:status=='waiting'?const Color(0xFFFFF7ED):const Color(0xFFECFDF5),borderRadius:BorderRadius.circular(20)),child:Text(label,style:TextStyle(fontSize:11,fontWeight:FontWeight.w700,color:status=='waiting'?const Color(0xFFC2410C):const Color(0xFF047857))));}}
class _Queue extends ConsumerWidget{const _Queue();@override Widget build(BuildContext c,WidgetRef ref){final ap=ref.watch(appointmentsProvider);return _Page(title:'الطابور',child:ap.when(data:(x)=>ListView(padding:const EdgeInsets.all(20),children:x.map((a)=>_AppointmentTile(a:a,doctor:true)).toList()),loading:()=>const _LoadingCards(),error:(e,_)=>_ErrorCard(message:e.toString(),onRetry:()=>ref.invalidate(appointmentsProvider))));}}
class _DoctorMessages extends StatelessWidget{const _DoctorMessages();@override Widget build(BuildContext c)=>const _Page(title:'الرسائل',child:_ComingSoon(icon:Icons.chat_rounded,text:'واجهة المحادثات ستُربط بالرسائل الحالية في الإصدار التالي.'));}
class _Profile extends ConsumerWidget{const _Profile();@override Widget build(BuildContext c,WidgetRef ref)=>_Page(title:'حسابي',child:ListView(padding:const EdgeInsets.all(20),children:[_ActionCard(icon:Icons.logout_rounded,title:'تسجيل الخروج',onTap:()async=>ref.read(authProvider.notifier).signOut())]));}
class _Page extends StatelessWidget{const _Page({required this.title,required this.child});final String title;final Widget child;@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,20,20,8),child:Align(alignment:Alignment.centerRight,child:Text(title,style:Theme.of(c).textTheme.headlineSmall))),Expanded(child:child)]);}
class _Nav extends StatelessWidget{const _Nav({required this.index,required this.onChanged,required this.labels,required this.icons});final int index;final ValueChanged<int> onChanged;final List<String> labels;final List<IconData> icons;@override Widget build(BuildContext c)=>NavigationBar(selectedIndex:index,onDestinationSelected:onChanged,height:76,destinations:[for(var i=0;i<labels.length;i++)NavigationDestination(icon:Icon(icons[i]),label:labels[i])]);}
