class _Empty extends StatelessWidget{const _Empty({required this.text});final String text;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(28),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(22)),child:Center(child:Text(text,style:const TextStyle(color:AppTheme.textSecondary))));}
class _ErrorCard extends StatelessWidget{const _ErrorCard({required this.message,required this.onRetry});final String message;final VoidCallback onRetry;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20)),child:Column(children:[const Icon(Icons.cloud_off_rounded,color:AppTheme.error,size:32),const SizedBox(height:8),Text('تعذر تحميل البيانات',style:Theme.of(c).textTheme.titleMedium),Text(message,textAlign:TextAlign.center,style:const TextStyle(color:AppTheme.textSecondary,fontSize:12)),TextButton(onPressed:onRetry,child:const Text('إعادة المحاولة'))]));}
