class _ComingSoon extends StatelessWidget{const _ComingSoon({required this.icon,required this.text});final IconData icon;final String text;@override Widget build(BuildContext c)=>Center(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:52,color:AppTheme.primary),const SizedBox(height:15),Text(text,textAlign:TextAlign.center,style:const TextStyle(color:AppTheme.textSecondary,height:1.6))])));}
